@spec cmgr_manifest_spec  src=tests/specs/cmgr_manifest_spec.lua  loc=106  cases=7

# Intent
  The manifest declares each command once, carrying its label and its keys.
  Pins that install writes those keys into the declaring scope's keymap, that
  a keyless entry binds nothing, that a name declared twice raises, and that
  the load-time audit raises in both directions, and on a scope that registers
  a command while declaring no manifest at all.

# Helpers
  @fn fresh()  @ 12
      -- Keyspecs are opaque to everything under test here, so plain strings stand
      -- in for ImGui key constants.
  @fn noop()  @ 14

# Cases
  @case 'install writes each entry\'s keys into its own scope\'s keymap'  [pure]  @ 18-30
  @case 'an entry with no keys binds nothing'  [pure]  @ 34-40
  @case 'a command declared by two scopes raises at install'  [pure]  @ 44-55
  @case 'audit is quiet when entries and registrations correspond'  [pure]  @ 59-69
  @case 'audit raises on a scope that registers but declares no manifest'  [pure]  @ 73-81
  @case 'audit raises on an entry no scope registers'  [pure]  @ 85-92
  @case 'audit raises on a registered command its scope does not declare'  [pure]  @ 96-104

